import type { AwsHighlight } from "./aws-highlights";

/**
 * Reference handbooks of the actual named things in six ecosystems: the
 * modules, packages, middleware, decorators, hooks and config keys a working
 * developer types out rather than the concepts behind them.
 *
 * The existing technology handbooks teach ideas — "Streams and backpressure",
 * "Guards and authorisation". These answer the other question, the one you ask
 * with a package name already in mind: what is `undici`, which Nest decorator
 * validates a body, what does `cacheLife` do. Keeping the two apart means
 * neither has to compromise: a concept list stays teachable, and a reference
 * list stays exhaustive.
 *
 * The Next.js entries below were checked against `node_modules/next/dist/docs`
 * for the installed version rather than written from memory, because this
 * release renamed and added enough API that memory is not reliable.
 */
export type PackageTopic = AwsHighlight;

const t = (name: string, category: string, summary: string): PackageTopic => ({ name, category, summary });

